package com.bank.risk.service;

import com.bank.risk.model.StreakResult;

import java.util.Arrays;
import java.util.logging.Logger;

// Kadane's algorithm: the most profitable contiguous run of trading days.
public class ProfitStreakAnalyzer {
    private static final Logger log = Logger.getLogger(ProfitStreakAnalyzer.class.getName());

    public StreakResult bestProfitStreak(int[] pnl) {
        if (pnl == null || pnl.length == 0) {
            throw new IllegalArgumentException("P&L sequence must be non-empty");
        }
        long currentMax = pnl[0];
        long globalMax = pnl[0];
        int tentativeStart = 0;
        int bestStart = 0;
        int bestEnd = 0;

        for (int i = 1; i < pnl.length; i++) {
            if (currentMax < 0) {
                // Running streak is dead weight: restart from today.
                currentMax = pnl[i];
                tentativeStart = i;
                final int day = i;
                log.fine(() -> "Streak negative; restarting at day " + day);
            } else {
                currentMax += pnl[i];
            }
            if (currentMax > globalMax) {
                globalMax = currentMax;
                bestStart = tentativeStart;
                bestEnd = i;
            }
        }
        StreakResult result = new StreakResult(globalMax, bestStart, bestEnd);
        log.info(() -> "Best profit streak over " + Arrays.toString(pnl) + " = " + result);
        return result;
    }
}
